      timestamp: System.monotonic_time(:nanosecond)
    }
    {:ok, state}
  end

  def handle_call({:tokenize, text, birth}, _from, state) do
    tokens = hybrid_tokenize(text, state.grid, birth)
    {:reply, tokens, state}
  end

  def handle_cast({:update_state, token}, state) do
    sum_emb = Enum.sum(token.embedding)
    harmony_delta = token.harmony * 0.1
    new_potential = state.potential + sum_emb * 0.01 + harmony_delta
    new_phase = state.quantum_phase + @pi / 180.0
    new_harmony = state.harmony_score + harmony_delta
    updated_state = %{state |
      potential: new_potential,
      quantum_phase: new_phase,
      harmony_score: new_harmony,
      timestamp: System.monotonic_time(:nanosecond)
    }
    {:noreply, updated_state}
  end

  defp hybrid_tokenize(text, grid, birth) do
    norm = text |> String.downcase() |> String.replace("-", " ") |> String.trim()
    graphs = String.graphemes(norm)
    glen = length(graphs)
    blen = max(length(birth), 1)
    Enum.with_index(graphs)
    |> Enum.map(fn {g, index} ->
      id = index
      lorenz = lorenz_embedding(id, index)
      len1 = length(@celestial_chart_1)
      len2 = length(@celestial_chart_2)
      w1 = :math.sin(id * 0.1) * 0.5 + 0.5
      w2 = 1.0 - w1
      deg = (Enum.at(@celestial_chart_1, rem(id, len1)) * w1) + (Enum.at(@celestial_chart_2, rem(index, len2)) * w2)
      phase_shift = :math.sin(id * 0.1 + deg)
      lorenz_shift = Enum.map(lorenz, fn v -> v + phase_shift end)
      denom = if glen > 1, do: glen - 1, else: 1
      spline_x = index / denom
      coeffs = List.duplicate(1.0, grid)
      spline_val = kan_spline_eval(spline_x, coeffs, grid)
      orb_mod = Enum.at(@synastry_orbs, rem(index, length(@synastry_orbs))) * 0.01
      emb = Enum.map(lorenz_shift, fn v -> v + spline_val + orb_mod end)
      %{id: id, ch: g, embedding: emb, harmony: deg}
    end)
  end

  defp lorenz_embedding(id, index) do
    sigma = 10.0
    rho = 28.0
    beta = 8.0 / 3.0
    dt = 0.01
    x0 = id * 0.1
    y0 = index * 2.0
    z0 = id * 0.05 + index * 0.05
    x1 = x0 + dt * (sigma * (y0 - x0))
    y1 = y0 + dt * (x0 * (rho - z0) - y0)
    z1 = z0 + dt * (x0 * y0 - beta * z0)
    phase = :math.sin(x1) * :math.cos(y1) * :math.sin(z1)
    sin_phase = :math.sin(phase)
    cos_phase = :math.cos(phase)
    base = [phase, sin_phase, cos_phase, sigma, rho, beta, x1, y1, z1]
    pad = List.duplicate(0.0, @dim - length(base))
    base ++ pad
  end

  defp kan_spline_eval(x, coeffs, grid) do
    knots = clamped_uniform_knots(grid, @degree)
    basis = b_spline_basis(x, knots, @degree)
    Enum.zip(basis, coeffs)
    |> Enum.reduce(0.0, fn {b, c}, acc -> acc + b * c end)
  end

  defp b_spline_basis(x, knots, 0) do
    num_knots = length(knots)
    for i <- 0..(num_knots - 2) do
      k_i = Enum.at(knots, i)
      k_i1 = Enum.at(knots, i + 1)
      if x >= k_i and x < k_i1, do: 1.0, else: 0.0
    end
  end

  defp b_spline_basis(x, knots, degree) do
    prev_basis = b_spline_basis(x, knots, degree - 1)
    num_prev_basis = length(prev_basis)
    for i <- 0..(num_prev_basis - 2) do
      k_i = Enum.at(knots, i)
      k_id = Enum.at(knots, i + degree)
      k_i1 = Enum.at(knots, i + 1)
      k_id1 = Enum.at(knots, i + degree + 1)
      b_i = Enum.at(prev_basis, i)
      b_i1 = Enum.at(prev_basis, i + 1)
      term1_denom = k_id - k_i
      term1 = if term1_denom != 0.0, do: (x - k_i) / term1_denom * b_i, else: 0.0
      term2_denom = k_id1 - k_i1
      term2 = if term2_denom != 0.0, do: (k_id1 - x) / term2_denom * b_i1, else: 0.0
      term1 + term2
    end
  end

  defp clamped_uniform_knots(grid, degree) do
    interior_count = max(grid - degree - 1, 0)
    left = List.duplicate(0.0, degree + 1)
    right = List.duplicate(1.0, degree + 1)
    interior = if interior_count > 0, do: Enum.map(1..interior_count, fn k -> k / (interior_count + 1.0) end), else: []
    left ++ interior ++ right
  end
end
