open import Data.Vec using (Vec; []; _∷_; lookup; tabulate; zipWith; map; take; drop; replicate; _++_)
open import Data.List as List using (List; []; _∷_; foldr)
open import Data.Float using (Float; _+_; _*_)
open import Relation.Binary.PropositionalEquality using (_≡_; refl)
open import Data.Fin using (Fin)

record Tensor (Shape : List ℕ) : Set where
  constructor tensor
  field
    data : Vec Float (foldr _*_ 1 Shape)

unflatten : (rows cols : ℕ) → Vec Float (rows * cols) → Vec (Vec Float cols) rows
unflatten zero _ _ = []
unflatten (suc r) c v = take c v ∷ unflatten r c (drop c v)

flatten : {A : Set} {m n : ℕ} → Vec (Vec A n) m → Vec A (m * n)
flatten [] = []
flatten (r ∷ rs) = r ++ flatten rs

dot-product : {n : ℕ} → Vec Float n → Vec Float n → Float
dot-product [] [] = 0.0
dot-product (x ∷ xs) (y ∷ ys) = (x * y) + dot-product xs ys

transpose : {m n : ℕ} → Vec (Vec Float n) m → Vec (Vec Float m) n
transpose {zero} {n} [] = replicate []
transpose {suc m} {n} (row ∷ rows) = zipWith _∷_ row (transpose rows)

matmul-data : {m n p : ℕ} → Vec (Vec Float n) m → Vec (Vec Float p) n → Vec (Vec Float p) m
matmul-data a b = let bᵀ = transpose b in map (λ a-row → map (dot-product a-row) bᵀ) a

matmul : {m n p : ℕ} → Tensor (m ∷ n ∷ []) → Tensor (n ∷ p ∷ []) → Tensor (m ∷ p ∷ [])
matmul {m} {n} {p} (tensor a-data) (tensor b-data) =
  let a-unflat = unflatten m n a-data in
  let b-unflat = unflatten n p b-data in
  let c-unflat = matmul-data a-unflat b-unflat in
  tensor (flatten c-unflat)

EmbeddingDim : ℕ
EmbeddingDim = 18432

embedding-layer : {seq-len vocab-size : ℕ} → Vec (Fin vocab-size) seq-len → Tensor (vocab-size ∷ EmbeddingDim ∷ []) → Tensor (seq-len ∷ EmbeddingDim ∷ [])
embedding-layer {seq-len} {vocab-size} tokens (tensor weights) =
  let
    unflattened-weights = unflatten vocab-size EmbeddingDim weights
    lookup-embedding : Fin vocab-size → Vec Float EmbeddingDim
    lookup-embedding token-id = lookup token-id unflattened-weights
  in
    tensor (flatten (map lookup-embedding tokens))
