    ensures valid_tensor(t, size)
    ensures v == old(t.val)
{
    unfold valid_tensor(t, size)
    v := t.val
    fold valid_tensor(t, size)
}

method tensor_set(t: Ref, v: Int, size: Int)
    requires valid_tensor(t, size)
    ensures valid_tensor(t, size)
    ensures t.val == v
{
