    unfold memory_safe(a, size)
    unfold memory_safe(b, size)
    var av: Int := a.val
    var bv: Int := b.val
    fold memory_safe(a, size)
    fold memory_safe(b, size)
    var result: Int := av * bv
    if (result > 1000000) {
        result := 1000000
    }
    if (result < -1000000) {
        result := -1000000
    }
    unfold valid_tensor(c, size)
    c.val := result
    fold memory_safe(c, size)
}

