    output := tensor_alloc(size)
    unfold memory_safe(input, size)
    var v: Int := input.val
    fold memory_safe(input, size)
    var mean: Int := v / 2
    var variance: Int := (v - mean) * (v - mean)
    var inv_std: Int := 1
    var normalized: Int := (v - mean) * inv_std
