---------------- MODULE Inference ----------------
EXTENDS Integers, FiniteSets, TLC, Sequences

CONSTANT NumWorkers, MaxRequests
ASSUME NumWorkers \in Nat \ {0}
ASSUME MaxRequests \in Nat \ {0}

VARIABLES state, requests, results, pc
vars == <<state, requests, results, pc>>
Workers == 1..NumWorkers

TypeOK ==
    /\ state \in [Workers -> {"idle", "computing"}]
    /\ requests \in SUBSET (1..MaxRequests)
    /\ results \in [1..MaxRequests -> STRING \cup {"PENDING"}]
    /\ pc \in [1..MaxRequests -> {"unsubmitted", "pending", "done"}]

Init ==
    /\ state = [w \in Workers |-> "idle"]
    /\ requests = {}
    /\ results = [req \in 1..MaxRequests |-> "PENDING"]
    /\ pc = [req \in 1..MaxRequests |-> "unsubmitted"]

SubmitRequest(req) ==
    /\ pc[req] = "unsubmitted"
    /\ requests' = requests \cup {req}
    /\ pc' = [pc EXCEPT ![req] = "pending"]
    /\ UNCHANGED <<state, results>>

AssignWork(w, req) ==
    /\ w \in Workers
    /\ state[w] = "idle"
    /\ req \in requests
    /\ state' = [state EXCEPT ![w] = "computing"]
    /\ requests' = requests \ {req}
    /\ UNCHANGED <<results, pc>>

CompleteWork(w, req, res) ==
    /\ w \in Workers
    /\ state[w] = "computing"
    /\ pc[req] = "pending"
    /\ state' = [state EXCEPT ![w] = "idle"]
    /\ results' = [results EXCEPT ![req] = res]
    /\ pc' = [pc EXCEPT ![req] = "done"]
    /\ UNCHANGED <<requests>>

Next ==
    \/ \E req \in 1..MaxRequests : SubmitRequest(req)
    \/ \E w \in Workers, req \in requests : AssignWork(w, req)
    \/ \E w \in Workers, req \in 1..MaxRequests, res \in STRING : CompleteWork(w, req, res)

Spec == Init /\ [][Next]_vars

Termination == \A req \in 1..MaxRequests : <>(pc[req] = "done")

=============================================================================
