#define DIM 8
#define LAYERS 3
#define THRESHOLD 10

typedef Neuron {
    int state;
    int bias;
}

Neuron network[LAYERS][DIM];
int weights[LAYERS][DIM][DIM];
bool active[LAYERS][DIM];

proctype Node(int l; int i) {
    int sum = 0;
    int j = 0;
    if
    :: l < LAYERS - 1 ->
        sum = 0;
        do
        :: j < DIM ->
            sum = sum + network[l][j].state * weights[l][j][i];
            j++;
        :: j == DIM -> break;
        od;
        network[l+1][i].state = sum + network[l+1][i].bias;
        if
        :: network[l+1][i].state > THRESHOLD -> active[l+1][i] = true;
        :: else -> skip;
        fi;
    :: else -> skip;
    fi
}

init {
    int l, i, j;
    atomic {
        l = 0;
        do
        :: l < LAYERS ->
            i = 0;
            do
            :: i < DIM ->
                network[l][i].state = 1;
                network[l][i].bias = 0;
                active[l][i] = false;
                i++;
            :: i == DIM -> break;
            od;
            l++;
        :: l == LAYERS -> break;
        od;

        l = 0;
        do
        :: l < LAYERS - 1 ->
            i = 0;
            do
            :: i < DIM ->
                j = 0;
                do
                :: j < DIM ->
                    weights[l][i][j] = 1;
                    j++;
                :: j == DIM -> break;
                od;
                i++;
            :: i == DIM -> break;
            od;
            l++;
        :: l == LAYERS - 1 -> break;
        od;
    }

    l = 0;
    do
    :: l < LAYERS - 1 ->
        i = 0;
        do
        :: i < DIM ->
            run Node(l, i);
            i++;
        :: i == DIM -> break;
        od;
        l++;
    :: l == LAYERS - 1 -> break;
    od;
}

ltl check_liveness { <> (active[LAYERS-1][0]) }
